import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const d=JSON.parse('{"title":"卦数第七","description":"杭氏易学 - 卦数第七","frontmatter":{"title":"卦数第七","description":"杭氏易学 - 卦数第七"},"headers":[],"relativePath":"zh/classics/hangshi/008.md","filePath":"zh/classics/hangshi/008.md"}'),r={name:"zh/classics/hangshi/008.md"};function i(n,p,c,_,o,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="卦数第七" tabindex="-1">卦数第七 <a class="header-anchor" href="#卦数第七" aria-label="Permalink to “卦数第七”">​</a></h1><p>“天一，地二。天三，地四。天五，地六。天七，地八。天九，地十。”又曰“天数二十有五，地数三十。天地之数，五十有五。”河图洛书之数，即此五十有五之数所分布而进退者也。圣人则图画卦，是故卦之数即图书之数，亦即天地之数也。“大衍之数五十，其用四十有九”者，所以衍《易》，即以衍此五十有五之数者也。自宋儒窜易经文，以“天一地二”一节，移置“大衍之数五十”以前，两数遂相混合，并为一谈。异论纷若，左支右吾，卒无是处。汉学家虽力纠其缪，而于两节之数理，亦未能分析清楚，与卦象《彖传》相证明。乃沿缪袭误，以迄于今。程朱而后，言《易》者皆崇理论，言象者已不多，言数者尤少。偶有一鳞半爪，又皆似是而非。同人讲习，几于无可取资。爰就所知，略贡刍荛。所憾数学既浅，又荒废日久，自知肤浅已甚。姑引其端，以待专家之续竟其绪也。</p><p>先天数</p><p>乾一，兑二，离三，震四，巽五，坎六，艮七，坤八之数，邵子《皇极经世》之数，所谓先天数也。相传康节从李挺之氏学《易》三年，未能窥其奥，请益于李，叩其要旨。李乃授以一二三四五六七八之八字，康节言下大悟，恍然于乾兑离震巽坎艮坤之天然位次，与数适合。而阴阳交错，顺逆往来，无不妙合。极深研几，遂得贯澈天人，成《皇极经世》一书。程子叹为内圣外王之学，朱子《木义》，又取其大小方圆各图，弁诸经首。其后言《易》者，即以先天数为易数。于卦爻《彖》、《象》之言数者，如“七日”“八月”“十年”“九陵”之类，悉以先天数当之，歧误乃不可究诘。夫邵子先天数，非不合也。特邵子别有妙悟，以一二三四五六七八为主，如算学之数根。乾兑离震巽坎艮坤，只为其数之符号耳，故用乾兑离震巽坎艮坤可也，用日月星辰水火土石亦无不可也。因邵子未尝以此注《易》，但借卦爻以演其数，而所得之数理，变化分合，仍能与《易》相符。所谓殊途同归，法异而实不异也。若以言《易》，则自当以乾兑离震巽坎艮坤为主。先后体用，各有其数。与邵子之数同出天一地二之十数 【邵子先天八卦数：乾1、兑2、离3、震4、巽5、坎6、艮7、坤8】</p><p>乾一对坤八，合九。兑二对艮七，合九。离三对坎六，合九。震四对巽五，合九。四九合三十六。乾阳三画，坤阴六画，合九。兑四画，艮五画，合九。离四画，坎五画，合九。震五画，巽四画，合九。四九亦合三十六。八卦相荡成六十四，除乾坤坎离颐中孚大小过八卦反覆不变，余五十六皆一卦反覆成二卦，实只二十八卦。合乾坤等不变之八卦，亦共合三十六卦。三十六者，六之自乘也。故邵子曰“三十六宫都是春”，乃用六藏九，为邵子之独有心得，别具用法。故依此数方位，与五行干支纳甲皆不相合。纳甲之象与乾一兑二之数无关，汉学家力辟先天卦位，而于乾一兑二之数，无能辩驳。偶有言者，亦隔靴搔痒，无当于理。兹另图先天八卦之合洛书河图数如下：</p><p>圣人则图画卦，卦数即图书之数。图书之一六，皆从下起，阳从一始，阴以六终，皆归藏于北方，未有从上起者。邵子先天数，独悟“易逆数也”一语，故反用图书而逆由乾位起一，藏九不用，为两数之对待。如洛书之藏十，其妙用在卦顺则数逆，卦逆则数顺，故仍不悖于阳顺阴逆之天则。错综变化，而无不相通。若论先天八卦之本数，则自当取则河图，阴逆阳顺，以合于一六二七三八四九之匹偶。而阴阳相对，皆得五数。如雷风一四合五也，水火二三合五也，山泽七八合十五，天地九六合十五，皆五也。仍以五为中枢。而一六为地雷复，九四为天风姤，二七为水泽节，三八为火山旅。所谓布五行于四时，无不合也。和而后月生，此纳甲所以用先天之象，而取后天之数也。此理千余年来，未有发明。由于不知阳顺阴逆之数，以邵氏之数，强解京、焦之《易》，纷纭纠结，遂莫可究诘矣。阳数顺由一始，为一三七九。阴数逆由四起，为四二八六。宋以后，皆以二四六八为阴数之用，此其根本之错误也。阳顺阴逆图数，余于庚申之秋，始由“乾乘六龙”一语悟得“乘六”之法，绘图以明之。始知极数定象，通变成文，参伍错综，皆在阳顺阴逆。而千余年来，似是而非之注释，均可一扫而空矣。图说另详《易数偶得》。</p><p>坎一坤二震三巽四离九艮八兑七乾六。乾坎相连，一与六合。坤兑相连，二与七合。震艮相连，三与八合。巽离相连，四与九合。水火金木之数，各有配合，独阙五十两数。非阙也，坎一离九合十，中央戊己，而坤艮二八，亦合十为丑未，皆五与十土数所分寄，方位与洛书合，而数亦兼符纳甲。其说已详《卦位》章先天纳甲图，兹不赘述。更以数之顺序，并列与洛书参照，则第一章二八易位，二五构精，两图之妙更可见矣。</p><p>（缺图）</p><p>坎离乾巽震兑坤艮皆相对，与卦位合。惟坤二与艮八之位互易，五运中枢，而十暗寓于八方。所谓通变化而行鬼神者，即在此坤艮易位之妙用。故曰“神枢鬼藏”，向来道家珍为神秘。非入其门奥者，不肯轻泄。实则邵子天根月窟，子正在丑，午正在未数言，已不啻明明揭示，特后人不自悟耳。</p><p>先后天八卦合数</p><p>先后天八卦，既各有其本位本数，而体用相生，升降变化，由合而分，亦由分而合。是以《易》之《彖》、《象》凡涉言数者，亦各有体用之不同。先天八卦本数者，以河图为体者也。后天八卦本数者，以洛书为体者也。先后天八卦合数者，兼先后天之象而纳十干之数者也。此数相传最古，虞氏《易》即用此数也。</p><p>（缺图）</p><p>古纳甲图：东方甲乙配乾坤，南方兑艮配丙丁，西方庚辛属震巽，而坎戊离己中央，因壬癸为乾坤兼纳也。此图壬癸居北属坎离，以坎离代乾坤。有作离一坎六.者，阴阳互根，亦自可通。并前两图合观之，当知邵子数与《易》之分别矣。</p><p>天地范围数</p><p>天地范围数，相传即《连山》卦数。因其以艮为始终，所谓“范围天地而不过，曲成万物而不遗”者也。略举例如左：</p><p>右图始艮一，终艮十，而又以艮七为用，象数体用皆艮，故有《连山》易数之名。虽未必即为《连山》，而其象则兼先后天，数则合河图洛书。与纳甲纳音，融会而贯通之者也。天地万物之数，莫能外于是矣。阳数极于九，阴数极于六。阳，天也。天之用皆见于地，故数至六而体全，得七而六数之用行也。太阳无七，太阴无十，而艮兼用一、七、十者，一始十终，七则具成终成始之用者也。</p><p>八卦成列数</p><p>夫《易》开物成务，冒天下之道，如斯而已者，非他，即天一，地二，天三，地四，天五，地六，天七，地八，天九，地十之数也。八卦成列，天地之数，分阴分阳，与八卦并列，而五位配合，五行生布也，干支属也。一始十终，顺往逆来，六十四卦先后天往复循环，周而复始，而数有不周，独阙西北。先天则艮阙，后天则乾无，而盈虚消长，于以无阀，皆出“乾知大始”。冒天下之道，以极天之数，定天下之象，通天下之志，定天下之业，断天下之疑，兴神物以前民用，尽在于斯矣。</p><p>坎子一，艮丑二寅三，震卯四，巽辰五巳六，离午七，坤未八申九，兑酉十，乾戌亥无数。子午南北至卯酉春秋分，寒暑往来，日月出入，先天咸无，后天乾无，皆以无出有。此《易》数之精义入神，《易》道之广大悉备，皆在此八卦成列之时位象数。宋后言《易》，先别门户，争道统，宗宋者以老庄之说为异端，宗汉者以先天卦位为不经，而《易》遂无从言矣。程传号为易学正宗，而程子《自序》，谓予所传者辞也，冀学者由辞以得其意。然《彖》、《象》十翼之辞，无一辞一字，不由象数而来。舍象数而言辞，辞乌从得哉！此图之数，前人所未言。清季青田端木鹤田氏始创为之图，简要精当，足与经传相参证。与旧有诸图会而通之，不但于数理之要领可得，而古今来占筮推步之本源，悉在于是矣。</p>',19)])])}const f=a(r,[["render",i]]);export{d as __pageData,f as default};
